import 'dart:io';
import 'dart:developer';
import 'dart:convert';
import 'dart:typed_data';

import 'package:flutter/material.dart';
import 'package:get/get.dart';
import 'package:heavek/constants/app_images.dart';
import 'package:heavek/utils/image_picker.dart';
import 'package:image_picker/image_picker.dart';
import 'package:permission_handler/permission_handler.dart';

/// ImageUploadController manages image upload functionality
/// 
/// Features:
/// - Pick images from camera or gallery
/// - Display uploaded images with fallback to default
/// - Show upload progress indicators
/// - Manage image state (File, URL, processing status)
/// - Convert uploaded images to base64 string
/// - Get image as byte array (Uint8List)
/// 
/// Usage:
/// ```dart
/// // In your widget:
/// final imageController = Get.find<ImageUploadController>();
/// 
/// // Show image picker
/// imageController.showImagePickerBottomSheet(context);
/// 
/// // Check if image is uploaded
/// bool hasImage = imageController.hasUploadedImage;
/// 
/// // Get current image file
/// File? imageFile = imageController.currentImageFile;
/// 
/// // Get base64 string
/// String base64 = imageController.getBase64String();
/// 
/// // Get base64 with data URL prefix
/// String dataUrl = imageController.getBase64String(includeDataUrlPrefix: true);
/// 
/// // Get image as bytes
/// Uint8List? bytes = imageController.getBase64AsBytes();
/// ```
class ImageUploadController extends GetxController {
  // Observable variables
  final Rx<File?> selectedImageFile = Rx<File?>(null);
  final RxBool isUploading = false.obs;
  final RxString imageUrl = ''.obs;
  final RxString base64String = ''.obs;

  // Get ImagePickerService instance
  final ImagePickerService _imagePickerService = ImagePickerService.instance;

  // Get the current image to display (either uploaded file or default)
  File? get currentImageFile => selectedImageFile.value;
  
  // Check if user has uploaded an image
  bool get hasUploadedImage => selectedImageFile.value != null;

  // Get the base64 string of the uploaded image
  String get currentBase64String => base64String.value;

  // Get default image path
  String get defaultImagePath => Assets.imagesDummyPlaceholder;

  /// Check camera permission
  Future<bool> _checkCameraPermission() async {
    log('🔍 Checking camera permission...');
    final status = await Permission.camera.status;
    log('📷 Camera permission status: $status');
    
    if (status.isGranted) {
      log('✅ Camera permission already granted');
      return true;
    }
    
    if (status.isDenied) {
      log('❌ Camera permission denied, requesting...');
      final result = await Permission.camera.request();
      log('📷 Camera permission request result: $result');
      return result.isGranted;
    }
    
    log('⚠️ Camera permission permanently denied or restricted');
    return false;
  }

  /// Check gallery permission
  Future<bool> _checkGalleryPermission() async {
    log('🔍 Checking gallery permission...');
    Permission permission;
    
    if (Platform.isAndroid) {
      log('🤖 Android detected, checking photos permission...');
      // For Android 13+ (API 33+), use READ_MEDIA_IMAGES
      // Check if photos permission is available
      try {
        await Permission.photos.request();
        permission = Permission.photos;
        log('✅ Using Permission.photos for Android');
      } catch (e) {
        // Fallback to storage permission for older Android versions
        permission = Permission.storage;
        log('⚠️ Fallback to Permission.storage for Android: $e');
      }
    } else {
      permission = Permission.photos;
      log('🍎 iOS detected, using Permission.photos');
    }
    
    final status = await permission.status;
    log('📸 Gallery permission status: $status');
    
    if (status.isGranted) {
      log('✅ Gallery permission already granted');
      return true;
    }
    
    if (status.isDenied) {
      log('❌ Gallery permission denied, requesting...');
      final result = await permission.request();
      log('📸 Gallery permission request result: $result');
      return result.isGranted;
    }
    
    log('⚠️ Gallery permission permanently denied or restricted');
    return false;
  }

  /// Show permission denied dialog
  void _showPermissionDeniedDialog(BuildContext context, String permissionType) {
    // Check if running on simulator
    if (isSimulator) {
      _showSimulatorPermissionDialog(context, permissionType);
    } else {
      _showRealDevicePermissionDialog(context, permissionType);
    }
  }

  /// Show permission dialog for simulator
  void _showSimulatorPermissionDialog(BuildContext context, String permissionType) {
    Get.dialog(
      AlertDialog(
        title: Text('Permission Required (Simulator)'),
        content: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text('This app needs $permissionType permission to function properly.'),
            SizedBox(height: 16),
            Text('In iOS Simulator:', style: TextStyle(fontWeight: FontWeight.bold)),
            SizedBox(height: 8),
            Text('1. Go to Settings app in simulator'),
            Text('2. Find your app in the list'),
            Text('3. Enable "$permissionType" permission'),
            Text('4. Return to this app'),
            SizedBox(height: 16),
            Text('Or use the "Test" button for testing without permissions.'),
          ],
        ),
        actions: [
          TextButton(
            onPressed: () => Get.back(),
            child: Text('Cancel'),
          ),
          TextButton(
            onPressed: () {
              Get.back();
              // Try to open simulator settings
              _openSimulatorSettings();
            },
            child: Text('Open Settings'),
          ),
        ],
      ),
    );
  }

  /// Show permission dialog for real device
  void _showRealDevicePermissionDialog(BuildContext context, String permissionType) {
    Get.dialog(
      AlertDialog(
        title: Text('Permission Required'),
        content: Text('This app needs $permissionType permission to function properly. Please enable it in settings.'),
        actions: [
          TextButton(
            onPressed: () => Get.back(),
            child: Text('Cancel'),
          ),
          TextButton(
            onPressed: () {
              Get.back();
              openAppSettings();
            },
            child: Text('Settings'),
          ),
        ],
      ),
    );
  }

  /// Try to open simulator settings
  void _openSimulatorSettings() {
    try {
      // This might not work in simulator, but we try anyway
      openAppSettings();
    } catch (e) {
      log('⚠️ Could not open settings in simulator: $e');
      // Show additional instructions
      Get.snackbar(
        'Simulator Settings',
        'Please manually open Settings app in simulator and enable permissions for this app.',
        duration: Duration(seconds: 5),
      );
    }
  }

  /// Convert image file to base64 string
  Future<String?> _convertImageToBase64(File imageFile) async {
    try {
      final bytes = await imageFile.readAsBytes();
      final base64Str = base64Encode(bytes);
      log('Image converted to base64 successfully, length: ${base64Str.length}');
      return base64Str;
    } catch (e) {
      log('Error converting image to base64: $e');
      return null;
    }
  }

  /// Pick image from camera
  Future<void> pickImageFromCamera() async {
    try {
      log('📷 Starting camera image pick...');
      isUploading.value = true;
      
      // Check camera permission first
      final hasPermission = await _checkCameraPermission();
      if (!hasPermission) {
        log('❌ Camera permission denied, showing dialog');
        _showPermissionDeniedDialog(Get.context!, 'camera');
        return;
      }
      
      log('✅ Camera permission granted, opening camera...');
      final XFile? pickedFile = await _imagePickerService.pickImageFromCamera();
      
      if (pickedFile != null) {
        log('📸 Image picked from camera: ${pickedFile.path}');
        final imageFile = File(pickedFile.path);
        selectedImageFile.value = imageFile;
        
        // Convert to base64
        log('🔄 Converting image to base64...');
        final base64Str = await _convertImageToBase64(imageFile);
        if (base64Str != null) {
          base64String.value = base64Str;
          log('✅ Image converted to base64 successfully, length: ${base64Str.length}');
        } else {
          log('❌ Failed to convert image to base64');
        }
      } else {
        log('⚠️ No image selected from camera');
      }
    } catch (e) {
      log('❌ Error picking image from camera: $e');
    } finally {
      isUploading.value = false;
      log('🏁 Camera pick process completed');
    }
  }

  /// Pick image from gallery
  Future<void> pickImageFromGallery() async {
    try {
      isUploading.value = true;
      
      // Check gallery permission first
      final hasPermission = await _checkGalleryPermission();
      if (!hasPermission) {
        _showPermissionDeniedDialog(Get.context!, 'photo library');
        return;
      }
      
      final XFile? pickedFile = await _imagePickerService.pickSingleImageFromGallery();
      
      if (pickedFile != null) {
        final imageFile = File(pickedFile.path);
        selectedImageFile.value = imageFile;
        
        // Convert to base64
        final base64Str = await _convertImageToBase64(imageFile);
        if (base64Str != null) {
          base64String.value = base64Str;
        }
        
        log('Image picked from gallery: ${pickedFile.path}');
      }
    } catch (e) {
      log('Error picking image from gallery: $e');
    } finally {
      isUploading.value = false;
    }
  }

  /// Show image picker bottom sheet
  void showImagePickerBottomSheet(BuildContext context) {
    // Check if running on simulator and add test option
    final isSim = isSimulator;
    log('🧪 Simulator check result: $isSim');
    
    if (isSim) {
      log('🧪 Running on simulator, showing test option');
      _showSimulatorImagePickerBottomSheet(context);
    } else {
      log('📱 Running on real device, showing normal picker');
      _imagePickerService.openProfilePickerBottomSheet(
        context: context,
        onCameraPick: () {
          Navigator.pop(context); // Close bottom sheet
          pickImageFromCamera();
        },
        onGalleryPick: () {
          Navigator.pop(context); // Close bottom sheet
          pickImageFromGallery();
        },
      );
    }
  }

  /// Force simulator mode for testing (call this method to test)
  void showTestImagePickerBottomSheet(BuildContext context) {
    log('🧪 Force showing test picker');
    _showSimulatorImagePickerBottomSheet(context);
  }

  /// Show simulator-specific image picker with test option
  void _showSimulatorImagePickerBottomSheet(BuildContext context) {
    showModalBottomSheet(
      context: context,
      backgroundColor: Colors.transparent,
      elevation: 0,
      builder: (_) {
        return Container(
          height: 280,
          child: Card(
            elevation: 0,
            margin: EdgeInsets.zero,
            shape: RoundedRectangleBorder(
              borderRadius: BorderRadius.only(
                topLeft: Radius.circular(16),
                topRight: Radius.circular(16),
              ),
            ),
            child: Column(
              mainAxisAlignment: MainAxisAlignment.spaceBetween,
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                Column(
                  children: [
                    SizedBox(height: 10),
                    Center(child: Icon(Icons.remove, color: Colors.black)),
                    Padding(
                      padding: EdgeInsets.all(20),
                      child: Text(
                        "Upload from (Simulator Mode)",
                        style: TextStyle(
                          fontSize: 16,
                          fontWeight: FontWeight.w600,
                        ),
                        textAlign: TextAlign.center,
                      ),
                    ),
                  ],
                ),
                IntrinsicHeight(
                  child: Row(
                    mainAxisAlignment: MainAxisAlignment.spaceEvenly,
                    children: [
                      GestureDetector(
                        onTap: () {
                          Navigator.pop(context);
                          pickImageFromCamera();
                        },
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.center,
                          children: [
                            Icon(Icons.camera_alt, color: Colors.blue),
                            SizedBox(height: 10),
                            Text('Camera'),
                          ],
                        ),
                      ),
                      Container(color: Colors.grey, width: 1.0),
                      GestureDetector(
                        onTap: () {
                          Navigator.pop(context);
                          pickImageFromGallery();
                        },
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.center,
                          children: [
                            Icon(Icons.photo_library, color: Colors.blue),
                            SizedBox(height: 10),
                            Text('Gallery'),
                          ],
                        ),
                      ),
                      Container(color: Colors.grey, width: 1.0),
                      GestureDetector(
                        onTap: () {
                          Navigator.pop(context);
                          testImageUpload();
                        },
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.center,
                          children: [
                            Icon(Icons.bug_report, color: Colors.orange),
                            SizedBox(height: 10),
                            Text('Test'),
                          ],
                        ),
                      ),
                    ],
                  ),
                ),
                Container(),
              ],
            ),
          ),
        );
      },
    );
  }

  /// Remove selected image (reset to default)
  void removeImage() {
    // Clean up test file if it exists
    if (selectedImageFile.value != null && 
        selectedImageFile.value!.path.contains('test_image_')) {
      try {
        selectedImageFile.value!.deleteSync();
        log('🗑️ Test image file deleted: ${selectedImageFile.value!.path}');
      } catch (e) {
        log('⚠️ Could not delete test image file: $e');
      }
    }
    
    selectedImageFile.value = null;
    imageUrl.value = '';
    base64String.value = '';
    log('Image removed, reset to default');
  }

  /// Set image URL (for when image is uploaded to server)
  void setImageUrl(String url) {
    imageUrl.value = url;
    log('Image URL set: $url');
  }

  /// Get base64 string with optional data URL prefix
  /// [includeDataUrlPrefix] - if true, returns "data:image/jpeg;base64," + base64 string
  String getBase64String({bool includeDataUrlPrefix = false}) {
    if (base64String.value.isEmpty) return '';
    
    if (includeDataUrlPrefix) {
      return 'data:image/jpeg;base64,${base64String.value}';
    }
    
    return base64String.value;
  }

  /// Get base64 string as bytes (Uint8List)
  Uint8List? getBase64AsBytes() {
    if (base64String.value.isEmpty) return null;
    
    try {
      return base64Decode(base64String.value);
    } catch (e) {
      log('Error decoding base64 string: $e');
      return null;
    }
  }

  /// Upload image to server (implement based on your backend API)
  /// This is a placeholder method - implement according to your backend requirements
  Future<String?> uploadImageToServer() async {
    if (selectedImageFile.value == null) return null;
    
    try {
      isUploading.value = true;
      
      // For now, return a placeholder URL
      await Future.delayed(Duration(seconds: 2)); // Simulate upload delay
      String mockUrl = 'https://example.com/uploaded_image_${DateTime.now().millisecondsSinceEpoch}.jpg';
      imageUrl.value = mockUrl;
      
      log('Image uploaded successfully: $mockUrl');
      return mockUrl;
      
    } catch (e) {
      log('Error uploading image: $e');
      return null;
    } finally {
      isUploading.value = false;
    }
  }

  /// Get image for display - returns File if available, otherwise null for default
  File? getImageForDisplay() {
    return selectedImageFile.value;
  }

  /// Check if image is being processed
  bool get isProcessing => isUploading.value;

  /// Test method for simulator - simulates image upload
  Future<void> testImageUpload() async {
    log('🧪 Testing image upload in simulator...');
    
    try {
      isUploading.value = true;
      
      // Simulate a delay like real image processing
      await Future.delayed(Duration(seconds: 1));
      
      // Create a test base64 string (1x1 pixel PNG)
      const testBase64 = '';
      
      // Set the base64 string
      base64String.value = testBase64;
      
      // Create a test image file for UI display
      // We'll create a temporary file with the test image data
      final tempDir = Directory.systemTemp;
      final testImageFile = File('${tempDir.path}/test_image_${DateTime.now().millisecondsSinceEpoch}.png');
      
      // Write the test image data to the file
      final imageBytes = base64Decode(testBase64);
      await testImageFile.writeAsBytes(imageBytes);
      
      // Set the file so the UI can display it
      selectedImageFile.value = testImageFile;
      
      log('✅ Test image upload completed');
      log('📊 Base64 length: ${testBase64.length}');
      log('📁 Test image file created: ${testImageFile.path}');
      log('🖼️ Image file size: ${imageBytes.length} bytes');
      
    } catch (e) {
      log('❌ Test image upload failed: $e');
    } finally {
      isUploading.value = false;
    }
  }

  /// Check if running on simulator
  bool get isSimulator {
    final isIOS = Platform.isIOS;
    final hasSimulatorEnv = Platform.environment['SIMULATOR_DEVICE_NAME'] != null ||
                           Platform.environment['SIMULATOR_ROOT'] != null ||
                           Platform.environment['SIMULATOR_UDID'] != null;
    
    final result = isIOS && hasSimulatorEnv;
    log('🔍 Simulator detection: iOS=$isIOS, hasSimulatorEnv=$hasSimulatorEnv, result=$result');
    log('🔍 Environment keys: ${Platform.environment.keys.where((k) => k.contains('SIMULATOR')).toList()}');
    
    return result;
  }

  @override
  void onClose() {
    // Clean up resources if needed
    super.onClose();
  }
}
